/**
 * Component: E-Commerce Delivery Truck Animation
 * Author: @bonheur-developer1 (https://tailwindflex.com/@bonheur-developer1)
 * Source: https://tailwindflex.com/@bonheur-developer1/e-commerce-delivery-truck-animation
 * Attribution: Créé par @bonheur-developer1 sur TailwindFlex
 * License: Open Source (TailwindFlex community)
 */
import React from "react";

export function ECommerceDeliveryTruckAnimation() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Delivery Bus Animation with Notification</title>

    <style>
        @keyframes moveBus {
            0% { transform: translateX(-100%); }
            70% { transform: translateX(80%); }
            100% { transform: translateX(80%); }
        }
        @keyframes movePackage {
            0% { opacity: 0; transform: translateY(0); }
            20% { opacity: 1; transform: translateY(0); }
            70% { opacity: 1; transform: translateY(0); }
            80% { opacity: 1; transform: translateY(-100px); }
            100% { opacity: 0; transform: translateY(-100px); }
        }
        @keyframes showNotification {
            0% { opacity: 0; transform: translateY(20px); }
            80% { opacity: 0; transform: translateY(20px); }
            90% { opacity: 1; transform: translateY(0); }
            100% { opacity: 1; transform: translateY(0); }
        }
        .bus-animation {
            animation: moveBus 8s linear infinite;
        }
        .package-animation {
            animation: movePackage 8s linear infinite;
        }
        .notification-animation {
            animation: showNotification 8s linear infinite;
        }
    </style>
</head>
<body class="bg-blue-50 min-h-screen flex items-center overflow-hidden">
    <div class="container mx-auto px-4 relative h-64">
        <!-- Road -->
        <div class="absolute bottom-0 left-0 right-0 h-16 bg-gray-700 flex items-center">
            <div class="w-full h-1 bg-yellow-300 relative overflow-hidden">
                <div class="absolute top-0 left-0 w-64 h-full bg-yellow-300 transform -translate-x-full road-line"></div>
            </div>
        </div>

        <!-- Bus -->
        <div class="bus-animation absolute bottom-16 left-0 w-48 md:w-64">
            <div class="relative">
                <!-- Bus body -->
                <div class="bg-yellow-400 h-24 rounded-lg p-2">
                    <!-- Windows -->
                    <div class="flex space-x-1 mb-1">
                        <div class="w-6 h-6 bg-blue-300 rounded"></div>
                        <div class="w-6 h-6 bg-blue-300 rounded"></div>
                        <div class="w-6 h-6 bg-blue-300 rounded"></div>
                    </div>
                    <!-- Package inside bus (visible at start) -->
                    <div class="package-animation absolute top-4 left-1/2 transform -translate-x-1/2">
                        <div class="w-12 h-8 bg-red-500 relative">
                            <div class="absolute top-0 left-0 right-0 h-2 bg-white opacity-50"></div>
                            <div class="absolute bottom-0 left-0 right-0 h-2 bg-white opacity-50"></div>
                        </div>
                    </div>
                </div>
                <!-- Bus front -->
                <div class="absolute top-4 -right-4 w-8 h-12 bg-yellow-500 rounded-r-lg"></div>
                <!-- Wheels -->
                <div class="absolute -bottom-2 left-4 w-8 h-8 bg-gray-800 rounded-full border-2 border-gray-600"></div>
                <div class="absolute -bottom-2 right-8 w-8 h-8 bg-gray-800 rounded-full border-2 border-gray-600"></div>
                <!-- Headlight -->
                <div class="absolute top-8 -right-4 w-2 h-4 bg-yellow-200 rounded-r"></div>
            </div>
        </div>

        <!-- Delivery destination -->
        <div class="absolute bottom-16 right-8 md:right-16 w-16 h-24 bg-green-500 flex flex-col items-center justify-end pb-2">
            <div class="w-12 h-8 bg-red-500 relative">
                <div class="absolute top-0 left-0 right-0 h-2 bg-white opacity-50"></div>
                <div class="absolute bottom-0 left-0 right-0 h-2 bg-white opacity-50"></div>
            </div>
            <div class="text-white text-xs mt-1">Delivery</div>
        </div>

        <!-- Package being delivered (flies up at end) -->
        <div class="package-animation absolute bottom-16 right-24 md:right-32">
            <div class="w-12 h-8 bg-red-500 relative">
                <div class="absolute top-0 left-0 right-0 h-2 bg-white opacity-50"></div>
                <div class="absolute bottom-0 left-0 right-0 h-2 bg-white opacity-50"></div>
            </div>
        </div>

        <!-- Delivery Notification -->
        <div class="notification-animation absolute top-8 left-1/2 transform -translate-x-1/2 bg-white p-4 rounded-lg shadow-lg border border-green-300 max-w-xs">
            <div class="flex items-center">
                <div class="bg-green-100 p-2 rounded-full mr-3">
                    <svg xmlns="http://www.w3.org/2000/svg" class="h-6 w-6 text-green-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M5 13l4 4L19 7" />
                    </svg>
                </div>
                <div>
                    <h3 class="font-bold text-gray-800">Delivery Successful!</h3>
                    <p class="text-sm text-gray-600">Your package has been delivered.</p>
                </div>
            </div>
        </div>
    </div>

    <!-- Road line animation -->
    <style>
        .road-line {
            animation: moveLine 1s linear infinite;
        }
        @keyframes moveLine {
            0% { transform: translateX(0); }
            100% { transform: translateX(100%); }
        }
    </style>
</body>
</html>" }} />
  );
}
